class Solution:
    def findWords(self, words: List[str]) -> List[str]:
        rows = [set("qwertyuiop"), set("asdfghjkl"), set("zxcvbnm")]
        res = []
        for w in words:
            lw = w.lower()
            r = next(s for s in rows if lw[0] in s)
            if all(c in r for c in lw):
                res.append(w)
        return res

