class Solution {
public:
    vector<string> findWords(vector<string>& words) {
        string rs[3] = {"qwertyuiop", "asdfghjkl", "zxcvbnm"};
        unordered_set<char> rows[3];
        for (int i = 0; i < 3; i++)
            rows[i] = unordered_set<char>(rs[i].begin(), rs[i].end());
        vector<string> res;
        for (auto& w : words) {
            int k = 0;
            char c0 = tolower(w[0]);
            while (!rows[k].count(c0)) k++;
            bool ok = true;
            for (char c : w)
                if (!rows[k].count(tolower(c))) { ok = false; break; }
            if (ok) res.push_back(w);
        }
        return res;
    }
};

