class Solution {
    public String[] findWords(String[] words) {
        String[] rs = {"qwertyuiop", "asdfghjkl", "zxcvbnm"};
        Set<Character>[] rows = new HashSet[3];
        for (int i = 0; i < 3; i++) {
            rows[i] = new HashSet<>();
            for (char c : rs[i].toCharArray()) rows[i].add(c);
        }
        List<String> res = new ArrayList<>();
        for (String w : words) {
            String lw = w.toLowerCase();
            int k = 0;
            while (!rows[k].contains(lw.charAt(0))) k++;
            boolean ok = true;
            for (char c : lw.toCharArray())
                if (!rows[k].contains(c)) { ok = false; break; }
            if (ok) res.add(w);
        }
        return res.toArray(new String[0]);
    }
}

